import pandas as pd,numpy as np
from sklearn.compose import ColumnTransformer
from sklearn.preprocessing import OneHotEncoder,StandardScaler,SplineTransformer
from sklearn.pipeline import make_pipeline
from sklearn.linear_model import Ridge
from scipy.optimize import differential_evolution, minimize
D=pd.read_csv('/work/alloy_pair_target_train.csv'); y=D.target
features=['C','Mn','Si','Cr','Ni','Mo','V','Nb','Co','Al','Ti','Cu','solutionizing_temp','aging_temp','aging_time','cooling_rate','heat_treatment','route']
X=D[features]
cat=['heat_treatment','route'];num=[x for x in features if x not in cat]
bounds=[(0,1.2),(0,2),(0,1.5),(0,22),(0,25),(0,6),(0,1.5),(0,1),(0,15),(0,2),(0,1.5),(0,3),(950,1250),(450,750),(1,50),(.1,100)]
# predict wrappers: optionally Fe added
for withfe in [False,True]:
 for knots,deg,a in [(3,3,.1),(3,3,1),(3,2,.1),(3,2,1),(4,3,1),(5,3,1)]:
  xx=X.copy(); nn=num.copy()
  if withfe:
   xx.insert(12,'Fe',100-xx.iloc[:,:12].sum(axis=1));nn=num[:12]+['Fe']+num[12:]
  pre=ColumnTransformer([('n',make_pipeline(StandardScaler(),SplineTransformer(n_knots=knots,degree=deg,include_bias=False)),nn),('c',OneHotEncoder(sparse_output=False,drop='first'),cat)])
  m=make_pipeline(pre,Ridge(alpha=a)).fit(xx,y)
  def pred(z,ht='quench_temper',route='wrought'):
   q=dict(zip(num,z));q.update(heat_treatment=ht,route=route)
   if withfe:q['Fe']=100-sum(z[:12])
   return m.predict(pd.DataFrame([q]))[0]
  bestall=None
  for ht in D.heat_treatment.unique():
   for route in D.route.unique():
    r=differential_evolution(lambda z:-pred(z,ht,route),bounds,tol=1e-9,popsize=20,maxiter=1000,seed=40,polish=True)
    if bestall is None or r.fun<bestall[0]:bestall=(r.fun,r.x,ht,route)
  print('\n',withfe,knots,deg,a,'train',np.mean((m.predict(xx)-y)**2)**.5,'MAX',-bestall[0],bestall[2:])
  print(dict(zip(num,np.round(bestall[1],4))), 'sum',bestall[1][:12].sum())
  # tune cooling rate to exact target if max above, while hold at max others - DE exact with regularization toward max center
  if -bestall[0]>1051:
   z=bestall[1].copy()
   # find process or composition single variable roots scanning bounds closest max
   from scipy.optimize import brentq
   roots=[]
   for j,b in enumerate(bounds):
    grid=np.linspace(*b,1001);vals=[]
    for v in grid:
     zz=z.copy();zz[j]=v; vals.append(pred(zz,bestall[2],bestall[3])-1051)
    for k in range(1000):
     if vals[k]*vals[k+1]<0:
      rr=brentq(lambda v: pred(np.r_[z[:j],v,z[j+1:]],bestall[2],bestall[3])-1051,grid[k],grid[k+1]);roots.append((abs(rr-z[j])/(b[1]-b[0]),j,rr))
   if roots:
    _,j,rr=min(roots);z[j]=rr
    print('TUNE',num[j],rr,pred(z,bestall[2],bestall[3]));print(np.round(z,5))

